/**
 * In-card reference rail: rendered inside the composer card's overlay anchor
 * (the card's top, above the textarea — the image-thumbnail position). A
 * single horizontally-scrollable row (fixed height), matching the composer
 * card's background so it reads as part of the input box. When cards are
 * present, `:has()` pushes the textarea down so text never hides underneath.
 */
export declare const STYLES = "\n.dsh_rf_rail {\n  box-sizing: border-box;\n  position: absolute;\n  top: 0;\n  left: 14px;\n  right: 14px;\n  z-index: 5;\n  display: flex;\n  align-items: center;\n  gap: 6px;\n  height: 40px;\n  padding: 0 2px;\n  overflow-x: auto;\n  overflow-y: hidden;\n  border-bottom: 1px solid var(--dsw-alias-border-l2-darkmode-thin);\n  background: var(--dsw-specific-input-major);\n}\n.dsh_rf_row {\n  display: inline-flex;\n  align-items: center;\n  gap: 6px;\n  flex: none;\n  height: 28px;\n  padding: 0 4px 0 10px;\n  border: 1px solid rgba(59, 130, 246, 0.45);\n  border-radius: 9px;\n  background: rgba(59, 130, 246, 0.08);\n}\n.dsh_rf_icon {\n  flex: none;\n  width: 14px;\n  height: 14px;\n  color: #3b82f6;\n}\n.dsh_rf_path {\n  max-width: 240px;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n  color: #3b82f6;\n  font-size: 13px;\n  line-height: 18px;\n}\n.dsh_rf_remove {\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  flex: none;\n  width: 20px;\n  height: 20px;\n  border: 0;\n  border-radius: 10px;\n  background: none;\n  color: var(--dsw-alias-label-dimmed);\n  cursor: pointer;\n  padding: 0;\n}\n.dsh_rf_remove svg {\n  width: 12px;\n  height: 12px;\n}\n.dsh_rf_remove:hover {\n  background: var(--dsw-alias-interactive-bg-hover);\n  color: var(--dsw-alias-label-primary);\n}\n/* Push the textarea down while reference cards are present, so text is never\n   hidden under the rail (the rail itself sits in the freed top area). */\n.uV2eYG_card:has([data-ref-file-overlay]) .uV2eYG_scroll {\n  padding-top: 42px;\n}\n";
